"""The core :class:`Table` data structure."""

from __future__ import annotations

from collections.abc import Callable, Iterable, Iterator, Mapping, Sequence
from typing import Any


class Table:
    """An in-memory table made of named columns and positional rows.

    Values are stored exactly as provided; conversion between strings and
    numbers is handled by the :mod:`tabular.cleaning` helpers.
    """

    def __init__(self, headers: Sequence[str], rows: Iterable[Sequence[Any]]) -> None:
        self.headers: list[str] = list(headers)
        self.rows: list[list[Any]] = [list(row) for row in rows]
        if self.headers:
            width = len(self.headers)
            for row in self.rows:
                if len(row) != width:
                    raise ValueError(
                        f"row has {len(row)} value(s) but table has {width} column(s)"
                    )

    @classmethod
    def from_dicts(
        cls,
        records: Iterable[Mapping[str, Any]],
        headers: Sequence[str] | None = None,
    ) -> Table:
        """Build a table from an iterable of mappings."""
        records = list(records)
        if headers is None:
            headers = list(records[0].keys()) if records else []
        rows = [[record.get(header) for header in headers] for record in records]
        return cls(headers, rows)

    @property
    def shape(self) -> tuple[int, int]:
        """Return ``(row_count, column_count)``."""
        return len(self.rows), len(self.headers)

    def __len__(self) -> int:
        return len(self.rows)

    def __iter__(self) -> Iterator[list[Any]]:
        return iter(self.rows)

    def __getitem__(self, index: int | slice) -> list[Any] | list[list[Any]]:
        return self.rows[index]

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Table):
            return NotImplemented
        return self.headers == other.headers and self.rows == other.rows

    def __repr__(self) -> str:
        return f"Table(rows={len(self.rows)}, columns={self.headers!r})"

    def _index(self, name: str) -> int:
        try:
            return self.headers.index(name)
        except ValueError:
            raise KeyError(
                f"column {name!r} not found; available columns: {self.headers}"
            ) from None

    def column(self, name: str) -> list[Any]:
        """Return the values of a single column."""
        index = self._index(name)
        return [row[index] for row in self.rows]

    def to_dicts(self) -> list[dict[str, Any]]:
        """Return the rows as a list of column-name-to-value mappings."""
        return [dict(zip(self.headers, row)) for row in self.rows]

    def add_column(self, name: str, values: Iterable[Any]) -> Table:
        """Return a copy with a new column appended."""
        values = list(values)
        if len(values) != len(self.rows):
            raise ValueError(
                f"column {name!r} has {len(values)} value(s) but table has "
                f"{len(self.rows)} row(s)"
            )
        rows = [row + [value] for row, value in zip(self.rows, values)]
        return Table(self.headers + [name], rows)

    def drop_columns(self, *names: str) -> Table:
        """Return a copy without the named columns."""
        drop = {self._index(name) for name in names}
        headers = [h for i, h in enumerate(self.headers) if i not in drop]
        rows = [[v for i, v in enumerate(row) if i not in drop] for row in self.rows]
        return Table(headers, rows)

    def rename_columns(self, mapping: Mapping[str, str]) -> Table:
        """Return a copy with columns renamed according to ``mapping``."""
        headers = [mapping.get(header, header) for header in self.headers]
        return Table(headers, self.rows)

    def select(self, *names: str) -> Table:
        """Return a copy containing only the named columns, in order."""
        indexes = [self._index(name) for name in names]
        headers = [self.headers[i] for i in indexes]
        rows = [[row[i] for i in indexes] for row in self.rows]
        return Table(headers, rows)

    def filter(self, predicate: Callable[[dict[str, Any]], bool]) -> Table:
        """Return a copy with only the rows for which ``predicate`` is true."""
        rows = [
            row
            for row in self.rows
            if predicate(dict(zip(self.headers, row)))
        ]
        return Table(self.headers, rows)

    def sort_by(
        self,
        name: str,
        *,
        reverse: bool = False,
        key: Callable[[Any], Any] | None = None,
    ) -> Table:
        """Return a copy sorted by a single column."""
        index = self._index(name)
        if key is not None:
            rows = sorted(
                self.rows, key=lambda row: key(row[index]), reverse=reverse
            )
        else:
            rows = sorted(self.rows, key=lambda row: row[index], reverse=reverse)
        return Table(self.headers, rows)

    def head(self, n: int = 5) -> Table:
        """Return the first ``n`` rows."""
        return Table(self.headers, self.rows[:n])

    def tail(self, n: int = 5) -> Table:
        """Return the last ``n`` rows."""
        return Table(self.headers, self.rows[-n:])

    def copy(self) -> Table:
        """Return a shallow copy of the table."""
        return Table(self.headers, self.rows)

"""Functions that clean and normalise tabular data.

Every function accepts a :class:`~tabular.table.Table` and returns a new
``Table``; the input is never modified.
"""

from __future__ import annotations

from collections.abc import Iterable, Sequence
from typing import Any

from .table import Table

DEFAULT_MISSING = frozenset(
    {"", "na", "n/a", "null", "none", "nan", "nil", "missing", "-"}
)


def is_missing(value: Any, missing: Iterable[str] = DEFAULT_MISSING) -> bool:
    """Return whether ``value`` counts as missing."""
    if value is None:
        return True
    if isinstance(value, str):
        return value.strip().lower() in {token.lower() for token in missing}
    return False


def _column_indexes(table: Table, columns: Sequence[str] | None) -> list[int]:
    if columns is None:
        return list(range(len(table.headers)))
    return [table._index(column) for column in columns]


def strip_whitespace(table: Table) -> Table:
    """Trim surrounding whitespace from headers and string values."""
    headers = [header.strip() for header in table.headers]
    rows = [
        [value.strip() if isinstance(value, str) else value for value in row]
        for row in table.rows
    ]
    return Table(headers, rows)


def standardize_headers(
    table: Table, *, lower: bool = True, separator: str = "_"
) -> Table:
    """Normalise header names into ``snake_case`` style identifiers."""
    headers = []
    for header in table.headers:
        cleaned = header.strip().replace(" ", separator).replace("-", separator)
        if lower:
            cleaned = cleaned.lower()
        headers.append(cleaned)
    return Table(headers, table.rows)


def replace_missing(
    table: Table, missing: Iterable[str] = DEFAULT_MISSING
) -> Table:
    """Replace missing tokens with ``None``."""
    rows = [
        [None if is_missing(value, missing) else value for value in row]
        for row in table.rows
    ]
    return Table(table.headers, rows)


def drop_empty_rows(table: Table) -> Table:
    """Drop rows whose every value is missing."""
    rows = [
        row for row in table.rows if any(not is_missing(value) for value in row)
    ]
    return Table(table.headers, rows)


def drop_empty_columns(table: Table) -> Table:
    """Drop columns whose every value is missing."""
    if not table.rows:
        return table.copy()
    keep = [
        index
        for index in range(len(table.headers))
        if any(not is_missing(row[index]) for row in table.rows)
    ]
    headers = [table.headers[index] for index in keep]
    rows = [[row[index] for index in keep] for row in table.rows]
    return Table(headers, rows)


def drop_missing(
    table: Table,
    *,
    columns: Sequence[str] | None = None,
    how: str = "any",
    missing: Iterable[str] = DEFAULT_MISSING,
) -> Table:
    """Drop rows containing missing values in the selected columns.

    ``how`` may be ``"any"`` (drop when at least one selected value is missing)
    or ``"all"`` (drop only when every selected value is missing).
    """
    if how not in {"any", "all"}:
        raise ValueError("how must be 'any' or 'all'")
    indexes = _column_indexes(table, columns)

    rows = []
    for row in table.rows:
        flags = [is_missing(row[index], missing) for index in indexes]
        discard = any(flags) if how == "any" else all(flags)
        if not discard:
            rows.append(row)
    return Table(table.headers, rows)


def fill_missing(
    table: Table,
    value: Any = None,
    *,
    columns: Sequence[str] | None = None,
    missing: Iterable[str] = DEFAULT_MISSING,
) -> Table:
    """Replace missing values in the selected columns with ``value``."""
    indexes = set(_column_indexes(table, columns))
    rows = [
        [
            value if index in indexes and is_missing(cell, missing) else cell
            for index, cell in enumerate(row)
        ]
        for row in table.rows
    ]
    return Table(table.headers, rows)


def drop_duplicates(
    table: Table, *, columns: Sequence[str] | None = None
) -> Table:
    """Drop duplicate rows, keeping the first occurrence."""
    indexes = _column_indexes(table, columns)
    seen: set[tuple[Any, ...]] = set()
    rows = []
    for row in table.rows:
        signature = tuple(row[index] for index in indexes)
        if signature not in seen:
            seen.add(signature)
            rows.append(row)
    return Table(table.headers, rows)


def _coerce_number(value: Any) -> Any:
    if not isinstance(value, str):
        return value
    text = value.strip()
    if text == "":
        return value
    try:
        return int(text)
    except ValueError:
        pass
    try:
        return float(text)
    except ValueError:
        return value


def coerce_numeric(
    table: Table, *, columns: Sequence[str] | None = None
) -> Table:
    """Convert numeric-looking strings into ``int`` or ``float``.

    Non-numeric values are left untouched.
    """
    indexes = set(_column_indexes(table, columns))
    rows = [
        [
            _coerce_number(cell) if index in indexes else cell
            for index, cell in enumerate(row)
        ]
        for row in table.rows
    ]
    return Table(table.headers, rows)

"""Summary statistics and exploratory analysis for :class:`Table` objects."""

from __future__ import annotations

import math
import statistics
from collections import Counter
from collections.abc import Sequence
from typing import Any

from .cleaning import DEFAULT_MISSING, is_missing
from .table import Table


def to_number(value: Any) -> float | None:
    """Return ``value`` as a float, or ``None`` if it is not numeric."""
    if isinstance(value, bool) or value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    if isinstance(value, str):
        text = value.strip().replace(",", "")
        if text == "":
            return None
        try:
            return float(text)
        except ValueError:
            return None
    return None


def _numeric(values: Sequence[Any]) -> list[float]:
    numbers = []
    for value in values:
        number = to_number(value)
        if number is not None and not math.isnan(number):
            numbers.append(number)
    return numbers


def missing_report(
    table: Table, *, missing: Sequence[str] = tuple(DEFAULT_MISSING)
) -> dict[str, int]:
    """Return the number of missing values per column."""
    return {
        header: sum(
            1
            for value in table.column(header)
            if value is None
            or (isinstance(value, str) and value.strip().lower() in set(missing))
        )
        for header in table.headers
    }


def numeric_summary(table: Table, column: str) -> dict[str, Any]:
    """Return descriptive statistics for a numeric column."""
    values = table.column(column)
    numbers = _numeric(values)
    summary: dict[str, Any] = {
        "column": column,
        "count": len(numbers),
        "missing": len(values) - len(numbers),
    }
    if not numbers:
        return summary

    summary.update(
        {
            "mean": statistics.fmean(numbers),
            "median": statistics.median(numbers),
            "stdev": statistics.stdev(numbers) if len(numbers) > 1 else 0.0,
            "minimum": min(numbers),
            "maximum": max(numbers),
            "total": math.fsum(numbers),
        }
    )
    return summary


def describe(table: Table) -> dict[str, dict[str, Any]]:
    """Return a per-column summary.

    Numeric columns get descriptive statistics; other columns get cardinality
    information.
    """
    report: dict[str, dict[str, Any]] = {}
    for header in table.headers:
        values = table.column(header)
        numbers = _numeric(values)
        if values and len(numbers) == len(values):
            report[header] = numeric_summary(table, header)
        else:
            counter = Counter(value for value in values if not is_missing(value))
            most_common = counter.most_common(1)
            report[header] = {
                "column": header,
                "count": len(values) - sum(
                    1 for value in values if is_missing(value)
                ),
                "unique": len(counter),
                "top": most_common[0][0] if most_common else None,
                "freq": most_common[0][1] if most_common else 0,
            }
    return report


def value_counts(
    table: Table,
    column: str,
    *,
    top: int | None = None,
    normalize: bool = False,
) -> list[tuple[Any, float]]:
    """Return ``(value, count)`` pairs ordered from most to least frequent."""
    counter = Counter(
        value for value in table.column(column) if not is_missing(value)
    )
    items = counter.most_common(top)
    total = sum(counter.values())
    if normalize and total:
        return [(value, count / total) for value, count in items]
    return [(value, float(count)) if normalize else (value, count) for value, count in items]


def correlation(table: Table, column_a: str, column_b: str) -> float | None:
    """Return the Pearson correlation between two columns.

    Returns ``None`` when the correlation is undefined (fewer than two paired
    numeric values, or no variance in one of the columns).
    """
    pairs = []
    for left, right in zip(table.column(column_a), table.column(column_b)):
        left_number = to_number(left)
        right_number = to_number(right)
        if left_number is not None and right_number is not None:
            pairs.append((left_number, right_number))

    if len(pairs) < 2:
        return None

    count = len(pairs)
    mean_a = sum(left for left, _ in pairs) / count
    mean_b = sum(right for _, right in pairs) / count
    covariance = sum(
        (left - mean_a) * (right - mean_b) for left, right in pairs
    )
    variance_a = sum((left - mean_a) ** 2 for left, _ in pairs)
    variance_b = sum((right - mean_b) ** 2 for _, right in pairs)

    if variance_a == 0 or variance_b == 0:
        return None
    return covariance / math.sqrt(variance_a * variance_b)


def infer_types(table: Table) -> dict[str, str]:
    """Classify each column as ``"numeric"``, ``"boolean"``, ``"text"`` or
    ``"empty"``."""
    types: dict[str, str] = {}
    for header in table.headers:
        values = [value for value in table.column(header) if not is_missing(value)]
        if not values:
            types[header] = "empty"
        elif all(isinstance(value, bool) for value in values) or all(
            str(value).strip().lower() in {"true", "false", "yes", "no"}
            for value in values
        ):
            types[header] = "boolean"
        elif all(to_number(value) is not None for value in values):
            types[header] = "numeric"
        else:
            types[header] = "text"
    return types

